// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address logAddr) public {
        vm.assume(logAddr != address(0));
        c.SetMinSum(1);
        c.SetLogFile(logAddr);
        c.Initialized();
        // General rule: after Initialized(), any attempt to change the log file must revert.
        bool ok;
        try c.SetLogFile(logAddr) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
